CREATE TABLE "agenda_cambiodisponibilidadpendiente" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fecha" date,
  "bloque_inicio" datetime,
  "bloque_fin" datetime,
  "motivo" text,
  "creado_en" timestamp,
  "profesional_id" integer,
  "servicio_id" integer
);

CREATE TABLE "agenda_diacerrado" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fecha" date,
  "motivo" varchar(200)
);

CREATE TABLE "agenda_historial_reserva" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "evento" varchar(20),
  "fecha_hora" timestamp,
  "servicio_nombre" varchar(150),
  "profesional_nombre" varchar(250),
  "estado" varchar(50),
  "motivo" text,
  "registrado_en" timestamp,
  "reserva_id" integer,
  "duracion_minutos" integer
);

CREATE TABLE "agenda_reserva_cita_temporal" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_key" varchar(40),
  "cart_item_key" varchar(36),
  "servicio_id" integer,
  "fecha" date,
  "hora" time,
  "duracion_minutos" integer,
  "vence_en" timestamp,
  "profesional_id" integer
);

CREATE TABLE "agenda_servicio_desactivado_personal" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "servicio_id" integer,
  "categoria_id" integer
);

CREATE TABLE "alerta_seguimiento" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mensaje" text,
  "fecha_programada" timestamp,
  "atendida" boolean DEFAULT false,
  "ficha_id" integer
);

CREATE TABLE "ficha_cliente" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "alergias_condiciones" text,
  "observaciones_generales" text,
  "created_at" timestamp,
  "updated_at" timestamp,
  "cliente_id" integer UNIQUE
);

CREATE TABLE "fichas_atencion_seguimiento" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "servicio" varchar(150),
  "precio" decimal(10,2),
  "fecha_atencion" timestamp,
  "proximo_recordatorio" timestamp,
  "recordatorio_enviado" boolean DEFAULT false,
  "recordatorio_enviado_en" timestamp,
  "created_at" timestamp,
  "clienta_id" integer
);

CREATE TABLE "fichas_clienta_seguimiento" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(200),
  "telefono" varchar(20) UNIQUE,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "historial_atencion" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fecha_atencion" timestamp,
  "notas_sesion" text,
  "tratamiento_recomendado" text,
  "ficha_id" integer
);

CREATE TABLE "material_cambios_cito" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descripcion" text,
  "fecha_cambio" timestamp,
  "ficha_id" integer
);

CREATE TABLE "carrito_detallepedido" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "modalidad_pago" varchar(20),
  "producto_id_catalogo" integer,
  "servicio_id_catalogo" integer,
  "nombre" varchar(150),
  "cantidad" integer DEFAULT 1,
  "precio_unitario" decimal(10,2),
  "monto_pagado" decimal(10,2),
  "reserva_id" integer,
  "pedido_id" integer
);

CREATE TABLE "carrito_pagosimulado" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "monto" decimal(12,2),
  "metodo" varchar(40) DEFAULT 'Pago ficticio',
  "estado" varchar(20) DEFAULT 'aprobado',
  "transaccion_id" varchar(36) UNIQUE,
  "creado_en" timestamp,
  "pedido_id" integer
);

CREATE TABLE "carrito_pedido" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "creado_en" timestamp,
  "total" decimal(12,2),
  "monto_pagado" decimal(12,2),
  "estado" varchar(20),
  "cliente_id" integer
);

CREATE TABLE "carrito_reservaproductocarrito" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_key" varchar(40),
  "producto_id" integer,
  "cantidad" integer,
  "vence_en" timestamp
);

CREATE TABLE "categoria" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100),
  "tipo" varchar(50),
  "activa" boolean DEFAULT true
);

CREATE TABLE "configuracion" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "clave" varchar(100) UNIQUE,
  "valor" text,
  "descripcion" text
);

CREATE TABLE "detalle_venta" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cantidad" integer DEFAULT 1,
  "subtotal" decimal(10,2),
  "producto_id" integer,
  "servicio_id" integer,
  "venta_id" integer
);

CREATE TABLE "disponibilidad" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "dia_semana" varchar(20),
  "hora_inicio" time,
  "hora_fin" time,
  "activo" boolean DEFAULT true,
  "profesional_id" integer,
  "servicio_id" integer,
  "fecha_especifica" date,
  "intervalo_minutos" integer,
  "descanso_inicio" time,
  "descanso_fin" time,
  "desactivado_por_personal" boolean DEFAULT false
);

CREATE TABLE "notificacion" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo" varchar(50),
  "mensaje" text,
  "leida" boolean DEFAULT false,
  "fecha_creacion" timestamp,
  "usuario_id" integer
);

CREATE TABLE "pago" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "monto" decimal(12,2),
  "metodo_pago" varchar(50),
  "estado_pago" varchar(50) DEFAULT 'Aprobado',
  "transaccion_id" varchar(150),
  "fecha_pago" timestamp,
  "venta_id" integer
);

CREATE TABLE "producto" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(150),
  "descripcion" text,
  "imagen_url" varchar(255),
  "precio" decimal(10,2),
  "stock" integer DEFAULT 0,
  "activo" boolean DEFAULT true,
  "categoria_id" integer
);

CREATE TABLE "profesional_categoria" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profesional_id" integer,
  "categoria_id" integer
);

CREATE TABLE "profesional_servicio" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profesional_id" integer,
  "servicio_id" integer
);

CREATE TABLE "programacion_recordatorio" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo" varchar(20),
  "desfase" integer,
  "fecha_hora_cita" timestamp,
  "programado_para" timestamp,
  "creado_en" timestamp,
  "enviado_en" timestamp,
  "reserva_id" integer
);

CREATE TABLE "recordatorio_enviado" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo" varchar(20),
  "email" varchar(254),
  "enviado_en" timestamp,
  "reserva_id" integer,
  "desfase" integer,
  "fecha_hora_cita" timestamp
);

CREATE TABLE "reserva" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fecha_hora" timestamp,
  "estado" varchar(50),
  "origen" varchar(50),
  "created_at" timestamp,
  "updated_at" timestamp,
  "cliente_id" integer,
  "creada_por_id" integer,
  "profesional_id" integer,
  "servicio_id" integer,
  "cambio_disponibilidad_id" integer,
  "cliente_nombre" varchar(200),
  "cliente_email" varchar(254),
  "cliente_telefono" varchar(30),
  "duracion_minutos" integer DEFAULT 30,
  "servicio_nombre" varchar(150),
  "motivo_cancelacion" text,
  "motivo_suspension" text,
  "respuesta_suspension" varchar(20),
  "viene_con_acompanante" boolean DEFAULT false
);

CREATE TABLE "rol" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(50) UNIQUE
);

CREATE TABLE "servicio" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(150),
  "descripcion" text,
  "imagen_url" varchar(255),
  "duracion_minutos" integer,
  "precio" decimal(10,2),
  "activo" boolean DEFAULT true,
  "categoria_id" integer
);

CREATE TABLE "usuario" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "password" varchar(128),
  "last_login" timestamp,
  "is_superuser" boolean,
  "nombre" varchar(100),
  "apellidos" varchar(100),
  "segundo_nombre" varchar(100),
  "telefono" varchar(20),
  "email" varchar(254) UNIQUE,
  "is_active" boolean DEFAULT true,
  "is_staff" boolean DEFAULT false,
  "acepta_terminos_at" timestamp,
  "deleted_at" timestamp,
  "created_at" timestamp,
  "rol_id" integer
);

CREATE TABLE "venta" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fecha_venta" timestamp,
  "total" decimal(12,2),
  "estado" varchar(50) DEFAULT 'Completada',
  "cliente_id" integer
);

